import math

import rclpy
from rclpy.node import Node

from sensor_msgs.msg import LaserScan, PointCloud2
from sensor_msgs_py import point_cloud2


class TreeObservation:
    def __init__(self, tree_type, x, y, dbh, distance=None):
        self.tree_type = tree_type
        self.x = x
        self.y = y
        self.dbh = dbh
        self.distance = distance


class DBHDetector(Node):
    def __init__(self):

        super().__init__("dbh_detector")

        self.scan_count = 0
        self.pointcloud_count = 0

        # Future:
        # populated from TreeLocation[]messages generated by Parrot

        self.tree_locations = []

        self.create_subscription(LaserScan, "/husky1/scan", self.scan_callback, 10)

        self.create_subscription(
            PointCloud2, "/husky1/camera/depth/points", self.pointcloud_callback, 10
        )

        self.get_logger().info("DBH Detector started")

    def scan_callback(self, msg):

        self.scan_count += 1

        if self.scan_count % 5 != 0:
            return

        # Noise filterin
        filtered_ranges = self.median_filter_ranges(msg.ranges)

        msg.ranges = filtered_ranges

        # Convert scan to XY points
        points = self.scan_to_points(msg)

        self.get_logger().info(f"Converted {len(points)} valid scan points")

        distances = [math.sqrt(x * x + y * y) for x, y in points]

        self.get_logger().info(f"Min distance = {min(distances):.2f} m")

        self.get_logger().info(f"Max distance = {max(distances):.2f} m")

        # Focus on nearby returns
        nearby_points = [
            p for p in points if 1.0 < math.sqrt(p[0] ** 2 + p[1] ** 2) < 5.0
        ]

        self.get_logger().info(f"Nearby points = {len(nearby_points)}")

        # Cluster nearby point
        clusters = self.cluster_points(nearby_points)

        self.get_logger().info(f"Found {len(clusters)} total clusters")

        # Debug cluster statistics
        for i, cluster in enumerate(clusters):
            if len(cluster) < 5:
                continue

            xs = [p[0] for p in cluster]
            ys = [p[1] for p in cluster]

            width_x = max(xs) - min(xs)
            width_y = max(ys) - min(ys)

            ratio = max(width_x, width_y) / max(min(width_x, width_y), 0.001)

            self.get_logger().info(
                f"Cluster {i}: "
                f"Points={len(cluster)} "
                f"Wx={width_x:.2f} "
                f"Wy={width_y:.2f} "
                f"Ratio={ratio:.2f}"
            )

        # Mesh-based tree filtering
        tree_clusters = [
            cluster
            for cluster in clusters
            if (8 < len(cluster) < 60 and self.is_tree_like(cluster))
        ]

        self.get_logger().info(f"Tree candidates = {len(tree_clusters)}")

        # Process candidate trees
        for i, cluster in enumerate(tree_clusters):
            dbh = self.estimate_dbh(cluster)

            _, width_x, width_y = self.estimate_diameter(cluster)

            ratio = max(width_x, width_y) / max(min(width_x, width_y), 0.001)

            distance = min(math.sqrt(x * x + y * y) for x, y in cluster)

            cx, cy = self.calculate_centroid(cluster)

            # Future:
            # convert centroid from local Husky frame into global map frame.
            global_x, global_y = self.local_to_global(cx, cy)

            observation = TreeObservation(
                tree_type="unknown", x=global_x, y=global_y, dbh=dbh, distance=distance
            )

            self.get_logger().info(
                f"Observation: "
                f"type={observation.tree_type}, "
                f"x={observation.x:.2f}, "
                f"y={observation.y:.2f}, "
                f"dbh={observation.dbh:.2f}"
            )

            self.get_logger().info(f"Tree {i}: Shape Ratio = {ratio:.2f}")

            self.get_logger().info(f"Tree {i}: Centre = ({cx:.2f}, {cy:.2f})")

    def pointcloud_callback(self, msg):
        self.get_logger().info(f"PointCloud frame = {msg.header.frame_id}")

        self.pointcloud_count += 1

        if self.pointcloud_count % 5 != 0:
            return

        points = self.pointcloud_to_points(msg)

        if not points:
            return

        self.get_logger().info(f"Raw cloud points = {len(points)}")

        height_filtered = self.filter_dbh_height(
            points,
            target_height=1.3,
            tolerance=0.10,
        )

        self.get_logger().info(f"After height filter = {len(height_filtered)}")

        range_filtered = height_filtered

        xs = [p[0] for p in height_filtered]
        ys = [p[1] for p in height_filtered]

        self.get_logger().info(
            f"Height slice X=[{min(xs):.2f},{max(xs):.2f}] "
            f"Y=[{min(ys):.2f},{max(ys):.2f}]"
        )

        for i in range(5):
            self.get_logger().info(f"Sample point {i}: {height_filtered[i]}")

        self.get_logger().info(f"After range filter = {len(range_filtered)}")

        filtered_points = range_filtered

        clusters = self.spatial_cluster_points(
            filtered_points,
            distance_threshold=0.03,
            min_cluster_size=20,
        )

        clusters = [c for c in clusters if 50 < len(c) < 2000]

        self.get_logger().info(f"Spatial clusters = {len(clusters)}")

        for i, cluster in enumerate(clusters):
            cx, cy = self.calculate_centroid(cluster)

            xs = [p[0] for p in cluster]
            ys = [p[1] for p in cluster]

            width_x = max(xs) - min(xs)
            width_y = max(ys) - min(ys)

            dbh = (width_x + width_y) / 2.0

            distances = [math.sqrt(x * x + y * y) for x, y in cluster]

            self.get_logger().info(
                f"Cluster {i}: "
                f"Points={len(cluster)} "
                f"Centre=({cx:.2f},{cy:.2f}) "
                f"MinDist={min(distances):.2f} "
                f"MaxDist={max(distances):.2f} "
                f"Wx={width_x:.2f} "
                f"Wy={width_y:.2f} "
                f"DBH={dbh:.2f}"
            )

    def filter_dbh_height(
        self,
        points,
        target_height=1.3,
        tolerance=0.15,
    ):
        return [(x, y) for x, y, z in points if abs(z - target_height) < tolerance]

    def pointcloud_to_points(self, msg):
        points = []

        for x, y, z in point_cloud2.read_points(
            msg,
            field_names=("x", "y", "z"),
            skip_nans=True,
        ):
            if math.isinf(x) or math.isinf(y) or math.isinf(z):
                continue
            points.append((x, y, z))

        return points

    # Noise filtering
    def median_filter_ranges(self, ranges):

        filtered = list(ranges)

        for i in range(1, len(ranges) - 1):
            values = [ranges[i - 1], ranges[i], ranges[i + 1]]

            valid = [v for v in values if not (math.isinf(v) or math.isnan(v))]

            if len(valid) == 3:
                filtered[i] = sorted(valid)[1]

        return filtered

    def scan_to_points(self, scan_msg):

        points = []

        angle = scan_msg.angle_min

        for r in scan_msg.ranges:
            if math.isinf(r) or math.isnan(r):
                angle += scan_msg.angle_increment
                continue

            x = r * math.cos(angle)
            y = r * math.sin(angle)

            points.append((x, y))

            angle += scan_msg.angle_increment

        return points

    def calculate_centroid(self, cluster):

        cx = sum(x for x, y in cluster) / len(cluster)

        cy = sum(y for x, y in cluster) / len(cluster)

        return cx, cy

    def match_tree_location(self, cx, cy, tree_x, tree_y):

        error = math.sqrt((cx - tree_x) ** 2 + (cy - tree_y) ** 2)

        return error

    def local_to_global(self, local_x, local_y):
        # TODO:
        # Use Husky pose to convert local cluster coordinates into the global map frame.

        return local_x, local_y

    def estimate_dbh(self, cluster):

        xs = [p[0] for p in cluster]
        ys = [p[1] for p in cluster]

        width_x = max(xs) - min(xs)
        width_y = max(ys) - min(ys)

        # Mesh-based approximation
        dbh = (width_x + width_y) / 2.0

        return dbh

    def estimate_agb(self, tree_type, dbh):
        # Placeholder.
        # Species-specific equations
        # added after confirmation.

        if tree_type == "oak":
            return 0.0

        elif tree_type == "pine":
            return 0.0

        return None

    def cluster_points(self, points, distance_threshold=0.20):

        if not points:
            return []

        clusters = []

        current_cluster = [points[0]]

        for i in range(1, len(points)):
            x1, y1 = points[i - 1]
            x2, y2 = points[i]

            distance = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

            if distance < distance_threshold:
                current_cluster.append(points[i])

            else:
                clusters.append(current_cluster)

                current_cluster = [points[i]]

        clusters.append(current_cluster)

        self.get_logger().info(f"cluster_points(): generated {len(clusters)} clusters")

        return clusters

    def spatial_cluster_points(
        self,
        points,
        distance_threshold=0.15,
        min_cluster_size=20,
    ):
        """
        Region-growing clustering for unordered depth-camera points.
        """

        if not points:
            return []

        clusters = []
        visited = set()

        for i in range(len(points)):
            if i in visited:
                continue

            cluster = []
            queue = [i]
            visited.add(i)

            while queue:
                current = queue.pop()

                cluster.append(points[current])

                x1, y1 = points[current]

                for j in range(len(points)):
                    if j in visited:
                        continue

                    x2, y2 = points[j]

                    distance = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

                    if distance < distance_threshold:
                        visited.add(j)
                        queue.append(j)

            if len(cluster) >= min_cluster_size:
                clusters.append(cluster)

        return clusters

    def is_tree_like(self, cluster):

        xs = [p[0] for p in cluster]
        ys = [p[1] for p in cluster]

        width_x = max(xs) - min(xs)
        width_y = max(ys) - min(ys)

        if width_x < 0.05 or width_y < 0.05:
            return False

        ratio = max(width_x, width_y) / min(width_x, width_y)

        return ratio < 8.0

    def estimate_diameter(self, cluster):

        xs = [p[0] for p in cluster]
        ys = [p[1] for p in cluster]

        width_x = max(xs) - min(xs)
        width_y = max(ys) - min(ys)

        diameter = max(width_x, width_y)

        return (diameter, width_x, width_y)


def main():

    rclpy.init()

    node = DBHDetector()

    rclpy.spin(node)

    node.destroy_node()

    rclpy.shutdown()


if __name__ == "__main__":
    main()
